ecc_agent_script_file.script:
# Define user, computer, and operating system variables
$username = $user
$computername = $compt
$os =  $ops

# Import Active Directory module
Import-Module ActiveDirectory -ErrorAction Stop

# Attempt to locate the user in AD
$user = Get-ADUser -Filter {
    SamAccountName -eq $username -or
    userPrincipalName -eq $username -or
    mail -eq $username
} -Properties DistinguishedName

# Exit if user not found
if (-not $user) {
    Write-Error "User '$username' not found."
    exit 1
}

# Get user's distinguished name
$dn = $user.DistinguishedName

# Check if any computer is already managed by this user
$managed = Get-ADComputer -Filter "ManagedBy -eq '$dn'" -Properties ManagedBy
if ($managed) {
    Write-Output "User '$username' already manages computer: $($managed.Name)"
    exit 0
}

# Try to find the computer in AD
$computer = Get-ADComputer -Filter "Name -eq '$computername'" -ErrorAction SilentlyContinue

if ($computer) {
    # Assign user as manager of existing computer
    Set-ADComputer -Identity $computername -ManagedBy $dn
    Write-Output "Existing computer '$computername' assigned to '$username'."
} else {
    # Create new computer object with OS attributes
    try {
        New-ADComputer -Name $computername `
                       -SamAccountName $computername `
                       -Path "OU=CorpComputers,DC=lmdcorp,DC=com" `
                       -ManagedBy $dn `
                       -Enabled $true `
                       -OtherAttributes @{
                           OperatingSystem = $os
                       }
        Write-Output "New computer '$computername' created for '$username' ."
    } catch {
        Write-Error "Failed to create computer '$computername': $_"
        exit 1
    }
}
